class StatementBacktrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)

  def ident(self, k):
    if k < len(self.src) and 'a' <= self.src[k] <= 'z':
      return k + 1
    return None

  def selector(self, k):
    while True:
      r = self.literal(k, '[')
      if r is not None:
        r = self.ident(r)
        if r is not None:
          r = self.literal(r, ']')
          if r is not None:
            k = r
            continue
      r = self.literal(k, '.')
      if r is not None:
        r = self.ident(r)
        if r is not None:
          k = r
          continue
      return k

  def statement(self, k):
    r = self.ident(k)
    if r is not None:
      r2 = self.selector(r)
      r3 = self.literal(r2, ':=')
      if r3 is not None:
        r4 = self.ident(r3)
        if r4 is not None:
          return r4
    r = self.ident(k)
    if r is not None:
      while True:
        r2 = self.literal(r, ',')
        if r2 is None:
          break
        r3 = self.ident(r2)
        if r3 is None:
          break
        r = r3
      r2 = self.literal(r, ':=')
      if r2 is not None:
        r3 = self.ident(r2)
        if r3 is not None:
          while True:
            r4 = self.literal(r3, ',')
            if r4 is None:
              break
            r5 = self.ident(r4)
            if r5 is None:
              break
            r3 = r5
          return r3
    r = self.ident(k)
    if r is not None:
      while True:
        r2 = self.literal(r, ',')
        if r2 is None:
          break
        r3 = self.ident(r2)
        if r3 is None:
          break
        r = r3
      r2 = self.literal(r, '←')
      if r2 is not None:
        r3 = self.ident(r2)
        if r3 is not None:
          r4 = self.literal(r3, '(')
          if r4 is not None:
            r5 = self.ident(r4)
            if r5 is not None:
              r6 = self.literal(r5, ')')
              if r6 is not None:
                return r6
    return None

  def parse(self, s: str):
    self.src = s
    return self.statement(0) == len(s)
